      const uploaded:Asset[]=[];
      if(files?.length)for(const file of Array.from(files)){const body=new FormData();body.append('file',file);const asset=await api<Asset>('/api/projects/'+project.id+'/assets',{method:'POST',body});await api<Take>('/api/projects/'+project.id+'/takes/import',{method:'POST',body:json({assetId:asset.id,name:file.name})});uploaded.push(asset);}
