      const next:Draft={...EMPTY_DRAFT,prompt,modelId:route.modelId,settings:{},inputAssetIds:route.inputAssetIds,sourceAssetId:Object.values(route.inputAssetIds).flat()[0]};
      localStorage.setItem('ots:draft:'+project.id,json(next));
